{%- assign v = product.selected_or_first_available_variant -%}
{%- assign transf = v.price | times: 90 | divided_by: 100 -%}

<div class="meli-cuotas">
  Mismo precio en 
  <strong>3 cuotas sin<br> interés de:</strong>
  <span class="meli-cuotas__amount" data-cuotas-amount>
    {{ v.price | divided_by: 3 | money }}
  </span>
</div>

<div class="meli-transf">
  <span class="meli-transf__amount" data-transf-amount>{{ transf | money }}</span>
  con transferencia
  <span class="meli-transf__badge">10% OFF</span>
</div>

<style>
.meli-cuotas{
  color:#00a650;
  font-size:13px;
  line-height:1.25;
  margin-top:4px;
}
.meli-cuotas strong{
  font-weight:600;
}
.meli-cuotas__amount{
  font-size:14px;
  font-weight:700;
  letter-spacing:.2px;
}
.meli-transf{
  color:#00a650;
  font-size:13px;
  line-height:1.25;
  margin-top:6px;
}
.meli-transf__amount{
  font-size:14px;
  font-weight:700;
  letter-spacing:.2px;
}
.meli-transf__badge{
  display:inline-block;
  background:#00a650;
  color:#fff;
  font-size:11px;
  font-weight:700;
  padding:1px 6px;
  border-radius:4px;
  margin-left:4px;
  vertical-align:1px;
}
</style>

<script>
(function(){
  var elCuotas = document.querySelector('[data-cuotas-amount]');
  var elTransf = document.querySelector('[data-transf-amount]');
  if(!elCuotas) return;

  function fmt(n){
    return '$' + n.toLocaleString('es-AR', {minimumFractionDigits:2, maximumFractionDigits:2});
  }
  // "$49.999,00" -> 49999.00
  function parseMoney(txt){
    if(!txt) return null;
    var m = txt.replace(/[^\d.,]/g, '').replace(/\./g, '').replace(',', '.');
    var n = parseFloat(m);
    return isNaN(n) ? null : n;
  }
  // total del bundle tildado en el widget de Kaching (selector exacto verificado)
  function selectedBundleTotal(){
    var checked = document.querySelector('.kaching-bundles__bar input:checked');
    var bar = checked && checked.closest ? checked.closest('.kaching-bundles__bar') : null;
    if(!bar) return null;
    var priceEl = bar.querySelector('.kaching-bundles__bar-price');
    return priceEl ? parseMoney(priceEl.textContent) : null;
  }
  function update(){
    var total = selectedBundleTotal();
    if(!total) return;
    elCuotas.textContent = fmt(total / 3);
    if(elTransf) elTransf.textContent = fmt(total * 0.9);
  }
  document.addEventListener('change', function(e){
    if(e.target.closest && e.target.closest('.kaching-bundles__bar')) setTimeout(update, 80);
  }, true);
  document.addEventListener('click', function(e){
    if(e.target.closest && e.target.closest('.kaching-bundles__bars')) setTimeout(update, 150);
  }, true);
  // sync inicial cuando el widget termina de montar (Lleva 2 viene preseleccionado)
  var tries = 0, t = setInterval(function(){
    if(selectedBundleTotal() !== null){ update(); clearInterval(t); }
    if(++tries > 40) clearInterval(t);
  }, 250);
})();
</script>

