<script>
(function(){
  const openBtn=document.querySelector('[data-mlpay-open]');
  const modal=document.querySelector('[data-mlpay-modal]');
  const closeBtn=document.querySelector('[data-mlpay-close]');
  const backdrop=document.querySelector('[data-mlpay-backdrop]');
  if(!openBtn||!modal||!closeBtn||!backdrop)return;

  function openModal(){
    modal.hidden=false;
    backdrop.hidden=false;
    document.documentElement.style.overflow='hidden';
  }

  function closeModal(){
    modal.hidden=true;
    backdrop.hidden=true;
    document.documentElement.style.overflow='';
  }

  openBtn.addEventListener('click',openModal);
  closeBtn.addEventListener('click',closeModal);
  backdrop.addEventListener('click',closeModal);
  document.addEventListener('keydown',e=>{
    if(e.key==='Escape'&&!modal.hidden)closeModal();
  });
})();
</script>

